      <li><b>\u5171\u901A\u8A2D\u5B9A</b>\uFF1AQualys \u63A5\u7D9A\u5148 POD\u3001\u30D7\u30ED\u30AD\u30B7 URL\u3001\u4FDD\u5B58\u671F\u9593\uFF08\u65E5\uFF09\u3001\u30E9\u30A4\u30BB\u30F3\u30B9\u4E0A\u9650\u3001\u56DB\u534A\u671F\u691C\u67FB\u306E\u5E74\u5EA6\u958B\u59CB\u6708\u30FB\u5BFE\u8C61\u306E\u63A5\u7D9A\u70B9ID \u30D1\u30BF\u30FC\u30F3\u3001\u691C\u67FB\u767B\u9332\u306E\u65E2\u5B9A\u5024\uFF08SCAN\uFF0FMAP \u306E\u30AA\u30D7\u30B7\u30E7\u30F3\u30D7\u30ED\u30D5\u30A1\u30A4\u30EB\u30FB\u30B9\u30AD\u30E3\u30CA\u30FC\u30FB\u30BF\u30A4\u30E0\u30BE\u30FC\u30F3\uFF09\u3002</li>
